import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const h=JSON.parse('{"title":"Filtro por trechos no campo de localizador secundário","description":"","frontmatter":{"title":"Filtro por trechos no campo de localizador secundário","id":"eploc-filtro-localizador-secundario","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.0.10","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eploc-filtro-localizador-secundario.md","filePath":"funcionalidades/eploc-filtro-localizador-secundario.md"}'),t={name:"funcionalidades/eploc-filtro-localizador-secundario.md"};function d(i,a,l,c,n,p){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="filtro-por-trechos-no-campo-de-localizador-secundario" tabindex="-1">Filtro por trechos no campo de localizador secundário <a class="header-anchor" href="#filtro-por-trechos-no-campo-de-localizador-secundario" aria-label="Permalink to &quot;Filtro por trechos no campo de localizador secundário&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>A busca do campo de localizadores secundários do eproc só encontra o texto digitado exatamente como está, em sequência. Com este recurso, você pode digitar trechos de palavras, em qualquer ordem, e a lista mostra só os localizadores que contêm todos eles.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, campo de localizadores secundários (por exemplo, no cadastro de minuta e na alteração de localizadores), na caixa de busca da lista.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a lista do campo de localizadores secundários.</li><li>Digite trechos separados por espaço, por exemplo <code>concl emenda</code> para achar &quot;Conclusos para decisão - Petição inicial emendada&quot;.</li><li>Use as setas para percorrer os resultados e Enter para marcar o destacado.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Busca aproximada (tolera abreviações e pequenos erros de digitação)</td><td>ligada</td><td>Também encontra localizadores com pequenas diferenças de grafia.</td></tr></tbody></table><p>Este interruptor também decide se o campo <strong>Novo localizador</strong> aceita vários trechos em qualquer ordem. Veja <a href="./eproc-filtro-novo-localizador">Filtro por trechos no campo de novo localizador</a>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nesta lista, os resultados não são reordenados por relevância: eles só são filtrados, na ordem do eproc.</li></ul>',12)]))}const m=o(t,[["render",d]]);export{h as __pageData,m as default};
